class LibraryMember {protected int borrowed;public LibraryMember(String id,int l){if(id==null||id.trim().length()<4||l<=0)throw new IllegalArgumentException();}public void borrowBook(){borrowed++;}public int getBooksBorrowed(){return borrowed;}public String displayInfo(){return "General | Books: "+borrowed;}}
class StudentMember extends LibraryMember {private String course;public StudentMember(String i,int l,String c){super(i,l);course=c;}public String getCourse(){return course;}@Override public String displayInfo(){return "Student | Course: "+course+" | Books: "+borrowed;}}
public class Problem4_WeeklyCirculationReport {static String batchPrint(LibraryMember[] ms){StringBuilder b=new StringBuilder();for(LibraryMember m:ms){if(b.length()>0)b.append(" | ");b.append(m.displayInfo());if(m instanceof StudentMember)b.append(" [Course via downcast: ").append(((StudentMember)m).getCourse()).append("]");}return b.toString();}public static void main(String[]x){System.out.println(batchPrint(new LibraryMember[]{new LibraryMember("LB5",3),new StudentMember("STU6",3,"ECE")}));}}